728	/// Rewrites a PEP 508 dependency constraint to pin it to `target`.
729	///
730	/// The following single-clause and two-clause forms are recognized and rewritten:
731	///
732	/// - `==X.Y.Z` — exact pin — is rewritten to `==NEW`.
733	/// - `~=X.Y.Z` — compatible release — is rewritten to `~=NEW`.
734	/// - `>=X.Y.Z` — lower bound only — is rewritten to `>=NEW`.
735	/// - `>=X.Y.Z,<A.B` — two-clause range — is rewritten to `>=NEW,<NEXT_MAJOR`
736	///   where `NEXT_MAJOR` equals `target.major() + 1`.
737	///
738	/// A pre-release or dev/local target (e.g. a `snapshot` version) is rendered
739	/// in full rather than truncated to `major.minor.patch`, the same precision
740	/// rule `cargo::round_trip` applies for SemVer.
741	///
742	/// All other forms return `None` — including upper-bound-only (`<`, `<=`),
743	/// exclusion (`!=`), compound expressions beyond the two-clause range above,
744	/// and wildcard `*`. Callers must leave the original constraint unchanged
745	/// when `None` is returned.
746	pub fn round_trip(spec: &DepSpec, target: &Version) -> Option<DepSpec> {
747	    // Only Range specs are produced by iter_dependencies for Python.
748	    let original = match spec {
749	        DepSpec::Range(_, raw) => raw.as_str(),
750	        _ => return None,
751	    };
752	
753	    let trimmed = original.trim();
754	
755	    // Compound range: ">=X.Y.Z,<A.B" → ">=NEW,<NEXT_MAJOR"
756	    if trimmed.contains(',') {
757	        return rewrite_range(trimmed, target);
758	    }
759	
760	    // Single-clause forms matched by their PEP 508 operator prefix.
761	    if trimmed.starts_with("==") {
762	        return rewrite_single(trimmed, "==", target);
763	    }
764	    if trimmed.starts_with("~=") {
765	        return rewrite_single(trimmed, "~=", target);
766	    }
767	    if trimmed.starts_with(">=") {
768	        return rewrite_single(trimmed, ">=", target);
769	    }
770	    // Poetry's own operators: bare caret and tilde (PEP 440's `~=` was handled above).
771	    if let Some(core) = trimmed.strip_prefix('^') {
772	        return rewrite_poetry_operator("^", core, target);
773	    }
774	    if let Some(core) = trimmed.strip_prefix('~').filter(|rest| !rest.starts_with('=')) {
775	        return rewrite_poetry_operator("~", core, target);
776	    }
777	
778	    // Unknown or unsupported form (e.g. "<", "<=", "!=", bare "*").
779	    None
780	}
