806	/// Rewrites a Poetry caret or tilde clause to the same window around the stable `target`; the caller writes it as the
807	/// equivalent PEP 440 range, which Poetry reads too. A pre-release target has no caret or tilde form, so it is left alone.
808	fn rewrite_poetry_operator(op: &str, core: &str, target: &Version) -> Option<DepSpec> {
809	    parse_version_core(core)?;
810	    if target.is_prerelease() {
811	        return None;
812	    }
813	    let rendered = format!("{op}{}", render_target(op, target)?);
814	    let req = VersionReq::parse(&normalize_poetry_version_spec(&rendered), Ecosystem::Pypi).ok()?;
815	    Some(DepSpec::Range(req, rendered))
816	}
