818	/// Renders `target` at the precision a rewritten spec should carry, for use after `op`:
819	/// `major.minor.patch` for a stable release; the version in full for a pre-release or
820	/// dev target paired with `==`/`!=` (the only operators PEP 440 allows on a local version);
821	/// the version with its local segment stripped for every other operator, since PEP 440
822	/// forbids `>=`, `<=`, `>`, `<` and `~=` from carrying one.
823	fn render_target(op: &str, target: &Version) -> Option<String> {
824	    if target.is_prerelease() {
825	        let full = target.render();
826	        if op == "==" || op == "!=" {
827	            return Some(full.to_string());
828	        }
829	        return Some(full.split('+').next().unwrap_or(full).to_string());
830	    }
831	    Some(format!("{}.{}.{}", target.major()?, target.minor()?, target.patch()?))
832	}
