834	/// Rewrites a two-clause `>=X.Y.Z,<A.B` range to `>=NEW,<NEXT_MAJOR`.
835	///
836	/// Returns `None` for anything that does not match exactly this two-clause
837	/// lower/upper pattern, including specs with three or more clauses (e.g.
838	/// `>=1.0,<2.0,!=1.5.0`) where silently dropping extra clauses would produce
839	/// a semantically incorrect constraint.
840	fn rewrite_range(original: &str, target: &Version) -> Option<DepSpec> {
841	    // Reject any spec with more than two comma-separated clauses: rewriting
842	    // would silently discard the extra clauses, changing the semantics.
843	    if original.split(',').count() != 2 {
844	        return None;
845	    }
846	
847	    let mut parts = original.splitn(2, ',');
848	    let lower = parts.next()?.trim();
849	    let upper = parts.next()?.trim();
850	
851	    // Lower clause must be `>=…`.
852	    if !lower.starts_with(">=") {
853	        return None;
854	    }
855	    // Upper clause must be strictly `<…` (not `<=`).
856	    if !upper.starts_with('<') || upper.starts_with("<=") {
857	        return None;
858	    }
859	
860	    // A window of one minor (`>=0.1.0,<0.2`) stays one minor wide; any other upper bound becomes the next major.
861	    let lower_core = lower
862	        .strip_prefix(">=")
863	        .and_then(|version| parse_version_core(version.trim()));
864	    let upper_core = upper
865	        .strip_prefix('<')
866	        .and_then(|version| parse_version_core(version.trim()));
867	    let one_minor_window = matches!(
868	        (lower_core, upper_core),
869	        (Some((lower_major, Some(lower_minor), _)), Some((upper_major, Some(upper_minor), upper_patch)))
870	            if upper_major == lower_major && upper_minor == lower_minor + 1 && upper_patch.unwrap_or(0) == 0
871	    );
872	    let upper_bound = if one_minor_window {
873	        format!("{}.{}", target.major()?, target.minor()? + 1)
874	    } else {
875	        (target.major()? + 1).to_string()
876	    };
877	    let rendered = format!(">={},<{upper_bound}", render_target(">=", target)?);
878	    let req = VersionReq::parse(&rendered, Ecosystem::Pypi).ok()?;
879	    Some(DepSpec::Range(req, rendered))
880	}
