/// `N!` for a version in epoch `N`, empty for epoch 0. Every bound written for a target needs it: an epoch outranks the
/// whole release segment, so a bound without it sits in epoch 0 and no longer bounds the target's epoch.
fn epoch_prefix(target: &Version) -> String {
    match target.epoch() {
        0 => String::new(),
        epoch => format!("{epoch}!"),
    }
}

